def modifyGraphEdges(n, edges, source, destination, target):
    INF = float('inf')

    # Adjacency list storing (neighbor, edge index)
    g = [[] for _ in range(n)]
    for i, (u, v, _) in enumerate(edges):
        g[u].append((v, i))
        g[v].append((u, i))

    # dis[v][0]: shortest distance when every -1 edge counts as 1
    # dis[v][1]: shortest distance in the second run, where -1 edges get adjusted weights
    dis = [[INF, INF] for _ in range(n)]
    dis[source] = [0, 0]

    def dijkstra(k, delta):
        # O(n^2) Dijkstra (n <= 100); run k picks which distance column to fill
        vis = [False] * n
        while True:
            x = -1
            for y in range(n):
                if not vis[y] and (x < 0 or dis[y][k] < dis[x][k]):
                    x = y
            if x < 0 or (k == 1 and x == destination):
                return
            vis[x] = True
            for y, eid in g[x]:
                wt = edges[eid][2]
                if wt == -1:
                    wt = 1
                    if k == 1:
                        # Make dis[x][1] + w equal dis[y][0] + delta, i.e. lengthen this edge so
                        # routes through it are exactly delta longer than the minimum (never < 1)
                        w = delta + dis[y][0] - dis[x][1]
                        if w > wt:
                            edges[eid][2] = wt = w
                dis[y][k] = min(dis[y][k], dis[x][k] + wt)

    # Run 1: all -1 edges are 1 -> the smallest possible shortest path
    dijkstra(0, 0)
    delta = target - dis[destination][0]
    if delta < 0:
        return []  # even the smallest possible distance exceeds target

    # Run 2: lengthen -1 edges on the fly so the distance can reach exactly target
    dijkstra(1, delta)
    if dis[destination][1] < target:
        return []  # fixed edges alone give a path shorter than target

    # Remaining -1 edges are not needed to reach target; set them to 1
    for e in edges:
        if e[2] == -1:
            e[2] = 1
    return edges
